/*
 * Elite - The New Kind.
 *
 * Nintendo 64: hardware-rendered ships ("Enhanced" graphics).
 */

#ifndef N64_SHIPS3D_H
#define N64_SHIPS3D_H

#include "space.h"

void hw_ships_init (void);
void hw_ships_set_light (double x, double y, double z);
int hw_ships_queue (struct univ_object *ship);
void hw_ships_flush (void);

/*
 * Replacement ship models (n64_shiptex.c, generated by
 * tools/gen_ship_textures.py from tools/convert_ship_model.py output).
 * A model is a list of batches; each batch is a set of vertices that fits
 * the RSP's vertex cache, the triangles that use them, and the texture
 * ("chart") they are drawn with.
 */
#define SHIP_MESH_STRIDE 11

struct ship_mesh_batch
{
	short chart;
	short num_verts;
	short num_tris;
	const short *verts;			/* SHIP_MESH_STRIDE per vertex: x, y, z, normal,
								 * u, v, smooth normal (normals x127) */
	const unsigned char *tris;	/* 3 per triangle */
};

struct ship_mesh
{
	int ship_type;
	int num_charts;
	const char *const *sprite_files;
	int num_batches;
	const struct ship_mesh_batch *batches;
};

extern const struct ship_mesh ship_meshes[];

/* Provided by n64_gfx.c */
int gfx_hw_available (void);
void gfx_hw_mark_busy (void);
void gfx_hw_wait (void);
void gfx_palette_rgb (int index, int *r, int *g, int *b);

#endif
